1093	+import { Component, computed, inject, signal } from '@angular/core';
1094	+
1095	+import { CatalogApiService } from '../catalog-api.service';
1096	+import { ProductSummary } from '../product.model';
1097	+
1098	+@Component({
1099	+  selector: 'app-product-list',
1100	+  templateUrl: './product-list.html'
1101	+})
1102	+export class ProductList {
1103	+  private catalogApi = inject(CatalogApiService);
1104	+
1105	+  protected readonly page = signal(1);
1106	+  protected readonly items = signal<ProductSummary[]>([]);
1107	+  protected readonly totalCount = signal(0);
1108	+  protected readonly loading = signal(false);
1109	+  protected readonly pageSize = signal(0);
1110	+
1111	+  protected readonly totalPages = computed(() => Math.max(1, Math.ceil(this.totalCount() / (this.pageSize() || 1))));
1112	+  protected readonly hasPreviousPage = computed(() => this.page() > 1);
1113	+  protected readonly hasNextPage = computed(() => this.page() * this.pageSize() < this.totalCount());
1114	+
1115	+  constructor() {
1116	+    this.loadPage(this.page());
1117	+  }
1118	+
1119	+  protected goToPreviousPage(): void {
1120	+    if (this.hasPreviousPage()) {
1121	+      this.loadPage(this.page() - 1);
1122	+    }
1123	+  }
1124	+
1125	+  protected goToNextPage(): void {
1126	+    if (this.hasNextPage()) {
1127	+      this.loadPage(this.page() + 1);
1128	+    }
1129	+  }
1130	+
1131	+  private loadPage(page: number): void {
1132	+    this.loading.set(true);
1133	+    this.catalogApi.getProducts(page).subscribe((response) => {
1134	+      this.page.set(response.page);
1135	+      this.items.set(response.items);
1136	+      this.totalCount.set(response.totalCount);
1137	+      this.pageSize.set(response.pageSize);
1138	+      this.loading.set(false);
1139	+    });
1140	+  }
1141	+}
